// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import {quadraticIntersectsBounds, quadraticBounds, segmentIntersectsBounds} from '../../../main/frontend/graph-explorer/graph-curve-collision.ts';
import {quadraticPoint} from '../../../main/frontend/graph-explorer/graph-geometry.ts';

const curve = (start, control, end) => ({start, control, end});
const box = {minX: -10, minY: -10, maxX: 10, maxY: 10};
test('analytic curve collision includes endpoints, tangencies and straight/degenerate curves', () => {
  assert.ok(quadraticIntersectsBounds(curve({x: 0, y: 0}, {x: 0, y: 500}, {x: 0, y: 1000}), box));
  assert.ok(quadraticIntersectsBounds(curve({x: -100, y: 110}, {x: 0, y: -90}, {x: 100, y: 110}), box));
  assert.ok(quadraticIntersectsBounds(curve({x: -1000, y: 0}, {x: 0, y: 0}, {x: 1000, y: 0}), box));
  assert.ok(quadraticIntersectsBounds(curve({x: 3, y: 3}, {x: 3, y: 3}, {x: 3, y: 3}), box));
  assert.equal(quadraticIntersectsBounds(curve({x: -100, y: 111}, {x: 0, y: -89}, {x: 100, y: 111}), box), false);
  assert.equal(segmentIntersectsBounds({x: -100, y: 11}, {x: 100, y: 11}, box), false);
  assert.equal(segmentIntersectsBounds({x: -100, y: 10}, {x: 100, y: 10}, box), true);
});
test('curve bounds and collision do not miss densely sampled points, including translated coordinates', () => {
  let state = 42;
  const random = () => ((state = (Math.imul(state, 1664525) + 1013904223) >>> 0) / 2 ** 32 * 1000 - 500);
  for (let i = 0; i < 1500; i++) {
    const offset = i % 2 ? 1e9 : 0;
    const point = () => ({x: random() + offset, y: random() + offset});
    const c = curve(point(), point(), point()), center = point();
    const b = {minX: center.x - 30, minY: center.y - 25, maxX: center.x + 30, maxY: center.y + 25};
    const bounds = quadraticBounds(c); let hit = false;
    for (let j = 0; j <= 500; j++) {
      const p = quadraticPoint(c.start, c.control, c.end, j / 500);
      assert.ok(p.x >= bounds.minX - 1e-6 && p.x <= bounds.maxX + 1e-6 && p.y >= bounds.minY - 1e-6 && p.y <= bounds.maxY + 1e-6);
      hit ||= p.x >= b.minX && p.x <= b.maxX && p.y >= b.minY && p.y <= b.maxY;
    }
    if (hit) assert.equal(quadraticIntersectsBounds(c, b), true);
  }
});
